    const m11 = gft_add_mant(40, 40, 352, 32);
    const m12 = gft_add_mant(40, 40, 384, 128);
    const m13 = gft_add_mant(40, 40, 416, 224);
    const m14 = gft_add_mant(40, 40, 448, 320);
    const m15 = gft_add_mant(40, 40, 480, 416);
